  window.certNextMissing=function(){const record=certificateRecords.find(function(item){return item.id===certificateActiveId;});if(!record)return;const pending=ceMissing(record).concat(ceReviewKeys(record));if(!pending.length){showToast("当前字段已完成并核对","ok");return;}const element=document.querySelector(".cert-field.missing input,.cert-field.missing select,.cert-field.missing textarea,.cert-field.needs-review input,.cert-field.needs-review select,.cert-field.needs-review textarea");if(element){element.focus();element.scrollIntoView({behavior:"smooth",block:"center"});}};
