    const files=Array.from(fileList||[]).filter(function(file){return /^image\/(jpeg|png|webp)$/.test(file.type||"");});if(!files.length){showToast("请选择 JPG、PNG 或 WebP 证书图片","warn");return;}const tooLarge=files.find(function(file){return file.size>20*1024*1024;});if(tooLarge){showToast("图片“"+tooLarge.name+"”超过 20MB","warn");return;}
